import { numberToWords } from './number-to-words.utils';
import { getPaymentModeLabel } from './payment-mode.utils';
import { formatCurrency } from '@angular/common';

const SKS_LOGO_DATA_URL = 'data:image/png;base64,';
const SKS_HEADER_DATA_URL = 'data:image/jpeg;base64,';


export interface ReceiptPrintData {
  receiptNumber: string;
  /** Primary payer name (student or enquiry person). */
  payerName: string;
  /**
   * Roll number — shown only after roll number generation.
   * When present, takes priority over admissionNumber for display.
   */
  payerIdentifier?: string | null;
  /** Admission number — shown after admission and before roll number generation. */
  admissionNumber?: string | null;
  /** Course/program name shown as "Course:" row. */
  programName?: string | null;
  amountPaid: number;
  paymentDate: string;
  paymentMode: string;
  transactionReference?: string | null;
  installmentBreakdown: Array<{ installmentLabel: string; amountApplied: number }>;
  /** Determines "towards" label: TUITION_AND_HOSTEL → "Tuition Fees And Hostel Fees", TUITION_ONLY → "Tuition Fees" */
  feeCategory?: 'TUITION_ONLY' | 'TUITION_AND_HOSTEL' | null;
}

// ── Internal: receipt CSS ─────────────────────────────────────────────────────

function buildReceiptCss(): string {
  return `
  @page { size: A5 landscape; margin: 5mm; }
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    width: 210mm;
    min-height: 148mm;
    overflow: visible;
  }
  body {
    font-family: 'Times New Roman', Times, serif;
    font-size: 12.5px;
    background: #fff;
    color: #000;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
  @media screen {
    html { background: #888; display: flex; justify-content: center; align-items: flex-start; padding: 16px; }
    body { box-shadow: 0 2px 12px rgba(0,0,0,0.4); }
  }

  /* ── Page shell: adds a safe top inset so PDF viewers never crop the header ── */
  .receipt-page {
    width: 100%;
    height: 138mm;
    display: flex;
    align-items: stretch;
  }

  .receipt {
    width: 100%;
    border: 3px double #1a237e;
    padding: 8px 14px 10px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  /* ── Header ── */
  .header { padding-bottom: 8px; border-bottom: 1.5px solid #1a237e; margin-bottom: 0; }
  .header-img { display: block; width: 75%; height: auto; margin: 0 auto; }

  /* ── Meta row: Receipt No (left) + Date (right) ── */
  .meta-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 46px;
    border-bottom: 1px solid #c5cae9;
    position: relative;
  }
  .receipt-no { font-size: 12.5px; }
  .receipt-no strong { font-size: 15px; }
  .doc-title { position: absolute; left: 50%; transform: translateX(-50%); text-align: center; font-size: 15px; font-weight: 900; letter-spacing: 2.5px; text-transform: uppercase; color: #1a237e; white-space: nowrap; }
  .meta-date { font-size: 12px; font-weight: 600; }

  /* ── Fill-in rows ── */
  .body { flex: 1; display: flex; flex-direction: column; justify-content: space-evenly; }
  .fill-row {
    display: flex;
    align-items: flex-end;
    font-size: 12.5px;
    line-height: 1;
  }
  .fill-label {
    white-space: nowrap;
    flex-shrink: 0;
    padding-right: 6px;
    padding-bottom: 7px;
    font-size: 13px;
    font-weight: 400;
  }
  .fill-blank {
    flex: 1;
    border-bottom: 1.5px dotted #555;
    min-width: 60px;
    padding-bottom: 7px;
  }
  .fill-blank--short { flex: 1; min-width: 80px; border-bottom: 1.5px dotted #555; padding-bottom: 7px; overflow: hidden; }
  .fill-blank--short .fill-value { padding-left: 16px; white-space: normal; word-break: break-word; }
  .fill-value {
    font-weight: 700;
    white-space: nowrap;
    padding-left: 0.45in;
    display: block;
    margin-bottom: 5px;
  }

  /* ── Footer (amount left, signature right) ── */
  .amount-box {
    border: 2px solid #1a237e;
    padding: 6px 16px;
    text-align: center;
    min-width: 130px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
  }
  .amount-label { font-size: 10px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #1a237e; }
  .amount-value { font-size: 20px; font-weight: 900; margin-top: 3px; color: #1a237e; }
  .footer-area { display: flex; flex-direction: column; }
  .footer-divider { border-top: 1.5px solid #1a237e; margin-bottom: 0; }
  .footer-content { flex: 1; display: flex; flex-direction: column; justify-content: center; padding: 6px 0; }
  .footer { display: flex; justify-content: space-between; align-items: flex-end; }
  .sig-block { text-align: center; min-width: 190px; }
  .for-word { font-size: 10px; margin-bottom: 1px; }
  .for-college { font-size: 11.5px; font-weight: 800; letter-spacing: 0.4px; }
  .sig-space { height: 42px; }
  .sig-line-rule { border-top: 1px solid #000; }
  .sig-text { font-size: 10px; padding-top: 3px; }
  .fill-label--mid { padding-left: 18px; flex-shrink: 0; }
  `;
}

// ── Internal: receipt body HTML ───────────────────────────────────────────────

function buildReceiptBodyHtml(data: ReceiptPrintData): string {
  const amountWords = numberToWords(data.amountPaid);
  const paymentModeLabel = getPaymentModeLabel(data.paymentMode);
  // Append 'T00:00:00' to avoid UTC-to-local-timezone shift on ISO date strings
  const formattedDate = new Date(data.paymentDate + 'T00:00:00').toLocaleDateString('en-IN', {
    day: '2-digit', month: 'long', year: 'numeric',
  });
  const formattedAmount = formatCurrency(data.amountPaid, 'en-IN', '₹', 'INR', '1.0-0');
  const towards = data.feeCategory === 'TUITION_AND_HOSTEL'
    ? 'Tuition Fees And Hostel Fees'
    : data.feeCategory === 'TUITION_ONLY'
      ? 'Tuition Fees'
      : data.installmentBreakdown.length
        ? data.installmentBreakdown
            .map(s => `${s.installmentLabel} (${formatCurrency(s.amountApplied, 'en-IN', '₹', 'INR', '1.0-0')})`)
            .join(', ')
        : 'Fee Payment';

  const rollNoInline = data.payerIdentifier
    ? `<span class="fill-label fill-label--mid">Roll No.</span>
      <span class="fill-blank"><span class="fill-value">${data.payerIdentifier}</span></span>`
    : '';
  const admissionRow = data.admissionNumber
    ? `<div class="fill-row">
      <span class="fill-label">Admission No.</span>
      <span class="fill-blank"><span class="fill-value">${data.admissionNumber}</span></span>
    </div>`
    : '';

  const courseRow = data.programName
    ? `<div class="fill-row">
      <span class="fill-label">Course</span>
      <span class="fill-blank"><span class="fill-value">${data.programName}</span></span>
    </div>`
    : '';

  const refRow = data.transactionReference
    ? `<div class="fill-row">
      <span class="fill-label">Ref. No.</span>
      <span class="fill-blank"><span class="fill-value">${data.transactionReference}</span></span>
    </div>`
    : '';

  return `
<div class="receipt-page">
<div class="receipt">

  <!-- Header -->
  <div class="header">
    <img class="header-img" src="${SKS_HEADER_DATA_URL}" alt="SKS College Of Nursing" />
  </div>

  <!-- Receipt No (left) + Date (right) -->
  <div class="meta-row">
    <div class="receipt-no">No. <strong>${data.receiptNumber}</strong></div>
    <div class="doc-title">FEE RECEIPT</div>
    <div class="meta-date">Date : ${formattedDate}</div>
  </div>

  <!-- Fill-in rows -->
  <div class="body">
    <div class="fill-row">
      <span class="fill-label">Received with thanks from</span>
      <span class="fill-blank"><span class="fill-value">${data.payerName}</span></span>
      ${rollNoInline}
    </div>
    ${admissionRow}
    ${courseRow}
    <div class="fill-row">
      <span class="fill-label">the sum of Rupees</span>
      <span class="fill-blank"><span class="fill-value">${amountWords}</span></span>
    </div>
    <div class="fill-row">
      <span class="fill-label">by</span>
      <span class="fill-blank--short"><span class="fill-value">${paymentModeLabel}</span></span>
      <span class="fill-label fill-label--mid">towards</span>
      <span class="fill-blank"><span class="fill-value">${towards}</span></span>
    </div>
    ${refRow}
  </div>

  <!-- Footer: amount box left, signature right — centered in remaining space -->
  <div class="footer-area">
    <div class="footer-divider"></div>
    <div class="footer-content">
      <div class="footer">
        <div class="amount-box">
          <div class="amount-label">Amount</div>
          <div class="amount-value">${formattedAmount} /-</div>
        </div>
        <div class="sig-block">
          <div class="for-word">For</div>
          <div class="for-college">SKS COLLEGE OF NURSING</div>
          <div class="sig-space"></div>
          <div class="sig-line-rule"></div>
          <div class="sig-text">Authorised Signature</div>
        </div>
      </div>
    </div>
  </div>

</div>
</div>`;
}

// ── Internal: PDF blob generator (used by all three exported actions) ─────────

async function generateReceiptPdfBlob(data: ReceiptPrintData): Promise<Blob> {
  // Dynamic import keeps html2pdf.js out of the main bundle until first use
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const h2p: (...args: unknown[]) => any = await import('html2pdf.js').then(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (m: any) => m.default ?? m,
  );

  // Inject the receipt into a hidden off-screen container so html2canvas can
  // capture it.  Width = printable content width of A5 landscape:
  //   210 mm − 2 × 5 mm = 200 mm
  const container = document.createElement('div');
  container.style.cssText =
    'position:fixed;left:0;top:0;width:200mm;height:138mm;background:#fff;' +
    'overflow:hidden;pointer-events:none;z-index:-9999;';
  container.setAttribute('aria-hidden', 'true');
  container.innerHTML = `<style>${buildReceiptCss()}</style>${buildReceiptBodyHtml(data)}`;
  document.body.appendChild(container);

  const captureEl = container.querySelector<HTMLElement>('.receipt-page');
  if (!captureEl) {
    document.body.removeChild(container);
    throw new Error('Receipt element not found for PDF generation');
  }

  const rect = captureEl.getBoundingClientRect();

  const opt = {
    margin: [5, 5, 5, 5], // top, right, bottom, left (mm)
    filename: `Receipt-${data.receiptNumber}.pdf`,
    image: { type: 'jpeg' as const, quality: 0.99 },
    html2canvas: {
      scale: 2,
      useCORS: true,
      logging: false,
      scrollX: 0,
      scrollY: 0,
      width: Math.ceil(rect.width),
      height: Math.ceil(rect.height),
      windowWidth: Math.ceil(rect.width),
      windowHeight: Math.ceil(rect.height),
    },
    jsPDF: { unit: 'mm' as const, format: 'a5', orientation: 'landscape' as const },
    pagebreak: { mode: [] as string[] }, // never break across pages
  };

  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return await h2p().set(opt).from(captureEl).toPdf().get('pdf').then((pdf: any) => {
      const pages = pdf.internal.getNumberOfPages();
      for (let i = pages; i > 1; i--) pdf.deletePage(i);
      // Tell PDF viewers to print at actual size (no fit-to-page scaling).
      // When printed on A4 portrait, A5 landscape content occupies the top half.
      pdf.viewerPreferences({ PrintScaling: 'None' });
      return pdf.output('blob') as Blob;
    });
  } finally {
    document.body.removeChild(container);
  }
}

// ── Exported: View — opens the receipt PDF in a new browser tab ───────────────

/**
 * Generates the fee receipt as a PDF and opens it in a new browser tab.
 * If a popup-blocker prevents the new tab, the PDF is downloaded instead.
 */
export async function printFeeReceipt(data: ReceiptPrintData): Promise<void> {
  const blob = await generateReceiptPdfBlob(data);
  const url = URL.createObjectURL(blob);
  const win = window.open(url, '_blank');
  if (!win) {
    // Popup blocked — fall back to direct download
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Receipt-${data.receiptNumber}.pdf`;
    document.body.appendChild(anchor);
    anchor.click();
    document.body.removeChild(anchor);
  }
  // Revoke after a generous delay so the opened tab has time to load
  setTimeout(() => URL.revokeObjectURL(url), 60_000);
}

// ── Exported: Download — saves the receipt as a .pdf file ────────────────────

/**
 * Generates the fee receipt as a PDF and triggers a browser file download.
 */
export async function downloadFeeReceipt(data: ReceiptPrintData): Promise<void> {
  const blob = await generateReceiptPdfBlob(data);
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = `Receipt-${data.receiptNumber}.pdf`;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  setTimeout(() => URL.revokeObjectURL(url), 5_000);
}

// ── Exported: Share — shares the receipt PDF via the Web Share API ────────────

/**
 * Generates the fee receipt as a PDF and shares it via the Web Share API.
 * If the browser supports file sharing, the PDF file is attached.
 * If only text sharing is supported, falls back to `shareText`.
 * Silently ignores user cancellation.
 */
export async function shareReceiptPdf(
  data: ReceiptPrintData,
  shareTitle: string,
  shareText: string,
): Promise<void> {
  if (typeof navigator === 'undefined' || !navigator.share) return;
  try {
    const blob = await generateReceiptPdfBlob(data);
    const file = new File([blob], `Receipt-${data.receiptNumber}.pdf`, {
      type: 'application/pdf',
    });
    if (navigator.canShare?.({ files: [file] })) {
      await navigator.share({ files: [file], title: shareTitle });
    } else {
      await navigator.share({ title: shareTitle, text: shareText });
    }
  } catch {
    /* User cancelled or share API error — silently ignore */
  }
}

